<!-- ── tools grid ── -->
<div class="section" id="tools">
  <div class="section-head reveal">
    <h2>The Toolkit</h2>
    <div class="section-rule"></div>
    <span class="section-label">9 tools</span>
  </div>

  <div class="tool-grid">

    <!-- TeqSlice -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon cyan">◫</div>
        <div class="card-meta">
          <div class="card-name">TeqSlice</div>
          <div class="card-url">teqxus.com/teqslice</div>
        </div>
        <span class="status new"><span class="pip"></span>New</span>
      </div>
      <p class="card-desc">A Photoshop-style image slicing tool that runs entirely in your browser. Draw slices, grid-cut sprite sheets, use guides, and bulk export to PNG, JPEG, WebP, TGA, BMP, TIFF, or ICO — straight into a folder you pick, or as a ZIP. Built for game devs and artists.</p>
      <div class="card-tags">
        <span class="tag">PWA</span><span class="tag">Offline</span><span class="tag">Sprite sheets</span><span class="tag">Batch export</span>
      </div>
      <div class="card-actions">
        <a href="https://teqxus.com/teqslice" class="btn-card primary">Open TeqSlice →</a>
        <a href="https://github.com/teqvault" class="btn-card ghost" target="_blank" rel="noopener">Source</a>
      </div>
    </div>

    <!-- TeqXus AI -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon purple">⚡</div>
        <div class="card-meta">
          <div class="card-name">TeqXus AI</div>
          <div class="card-url">teqxus.app</div>
        </div>
        <span class="status live"><span class="pip"></span>Live</span>
      </div>
      <p class="card-desc">A lightweight AI assistant built for low-data environments and multilingual communities across Africa and beyond. 7 languages, offline queue, and a $2.99/mo Pro tier that unlocks Claude Sonnet and unlimited daily messages.</p>
      <div class="card-tags">
        <span class="tag">AI</span><span class="tag">Offline-capable</span><span class="tag">7 languages</span><span class="tag">2G/3G</span>
      </div>
      <div class="card-actions">
        <a href="https://teqxus.app" class="btn-card primary" target="_blank" rel="noopener">Open TeqXus →</a>
      </div>
    </div>

    <!-- TeqDocs -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon amber">📖</div>
        <div class="card-meta">
          <div class="card-name">TeqDocs</div>
          <div class="card-url">teqxus.app/teqdocs</div>
        </div>
        <span class="status live"><span class="pip"></span>Live</span>
      </div>
      <p class="card-desc">A full offline document reader and writing companion. Opens PDF, Word, Markdown, and plain text with zero upload — files stay on your device. Annotate, sign, split, merge PDFs, write Markdown, and export in multiple formats.</p>
      <div class="card-tags">
        <span class="tag">PDF</span><span class="tag">Word</span><span class="tag">Markdown</span><span class="tag">Offline</span><span class="tag">Windows app</span>
      </div>
      <div class="card-actions">
        <a href="https://teqxus.app/teqdocs" class="btn-card primary" target="_blank" rel="noopener">Open TeqDocs →</a>
        <a href="https://github.com/teqvault/teqdocsDesktop/releases/download/2.0.0/TeqDocs.Student.Setup.2.0.0.exe" class="btn-card ghost">Download for Windows</a>
      </div>
    </div>

    <!-- TeqCarve -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon pink">🔍</div>
        <div class="card-meta">
          <div class="card-name">TeqCarve</div>
          <div class="card-url">github.com/teqvault</div>
        </div>
        <span class="status live"><span class="pip"></span>Live</span>
      </div>
      <p class="card-desc">A raw file carving and data recovery tool with both a CLI and a GUI. Recovers JPEG, PNG, HEIC, WebP, PDF, ZIP, Office documents, MP4, MP3, and more from raw disk images or damaged drives. Packaged as a standalone Windows executable — no Python required.</p>
      <div class="card-tags">
        <span class="tag">Data recovery</span><span class="tag">CLI + GUI</span><span class="tag">Windows</span><span class="tag">Offline</span>
      </div>
      <div class="card-actions">
        <a href="https://github.com/teqvault" class="btn-card primary" target="_blank" rel="noopener">Get TeqCarve →</a>
      </div>
    </div>

    <!-- TeqStudy -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon green">🎓</div>
        <div class="card-meta">
          <div class="card-name">TeqStudy</div>
          <div class="card-url">teqvault.study</div>
        </div>
        <span class="status live"><span class="pip"></span>Live</span>
      </div>
      <p class="card-desc">Interactive programming courses in plain HTML — no framework, no account, no build step. Java, Python, cybersecurity for beginners, and JUnit 5 unit testing. Runs offline. Designed around active recall and short lessons rather than passive video.</p>
      <div class="card-tags">
        <span class="tag">Java</span><span class="tag">Python</span><span class="tag">Cybersecurity</span><span class="tag">Offline</span><span class="tag">Free</span>
      </div>
      <div class="card-actions">
        <a href="https://teqvault.study" class="btn-card primary" target="_blank" rel="noopener">Open TeqStudy →</a>
      </div>
    </div>

    <!-- TeqDocs Military -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon teal">🪪</div>
        <div class="card-meta">
          <div class="card-name">TeqDocs Military</div>
          <div class="card-url">in development</div>
        </div>
        <span class="status dev"><span class="pip"></span>Dev</span>
      </div>
      <p class="card-desc">A DoD-compliant offline document platform built for military personnel. CAC/PIV digital signing, offline PDF editing, and form fill — no internet connection required for core functionality. Designed with OPSEC as a first principle, not an afterthought.</p>
      <div class="card-tags">
        <span class="tag">CAC signing</span><span class="tag">DoD</span><span class="tag">Offline</span><span class="tag">PDF</span>
      </div>
      <div class="card-actions">
        <span class="btn-card disabled">In Development</span>
      </div>
    </div>

    <!-- TeqVault IDE -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon cyan">💻</div>
        <div class="card-meta">
          <div class="card-name">TeqVault IDE</div>
          <div class="card-url">github.com/teqvault/teqIDE</div>
        </div>
        <span class="status new"><span class="pip"></span>New</span>
      </div>
      <p class="card-desc">A modern local-first web IDE with an AI assistant, Monaco-powered code editor, live preview, and an integrated knowledge base. Build once, run as a desktop app (Electron) or install as a PWA — no cloud dependency.</p>
      <div class="card-tags">
        <span class="tag">Code editor</span><span class="tag">AI assistant</span><span class="tag">Desktop app</span><span class="tag">PWA</span>
      </div>
      <div class="card-actions">
        <a href="https://github.com/teqvault/teqIDE/releases/download/1.0.0/Teq.Vault.IDE.Setup.0.1.0.exe" class="btn-card primary">Download for Windows</a>
        <a href="https://github.com/teqvault/teqIDE" class="btn-card ghost" target="_blank" rel="noopener">Source</a>
      </div>
    </div>

    <!-- TeqMusic -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon pink">🎵</div>
        <div class="card-meta">
          <div class="card-name">TeqMusic</div>
          <div class="card-url">Google Play · Android</div>
        </div>
        <span class="status live"><span class="pip"></span>Live</span>
      </div>
      <p class="card-desc">One player, two libraries: your own local music (never leaves your phone) plus the official Eyuforyia soundtrack, with offline downloads, real lyrics, and story fragments that unlock as you listen.</p>
      <div class="card-tags">
        <span class="tag">Android</span><span class="tag">Offline downloads</span><span class="tag">Lyrics</span><span class="tag">Lore unlocks</span>
      </div>
      <div class="card-actions">
        <a href="https://play.google.com/store/apps/details?id=com.teqvault.teqmusic" class="btn-card primary" target="_blank" rel="noopener">Get on Google Play →</a>
      </div>
    </div>

    <!-- TeqStream -->
    <div class="tool-card reveal">
      <div class="card-head">
        <div class="card-icon amber">📺</div>
        <div class="card-meta">
          <div class="card-name">TeqStream</div>
          <div class="card-url">Android · coming soon</div>
        </div>
        <span class="status dev"><span class="pip"></span>In Testing</span>
      </div>
      <p class="card-desc">One player for everything you watch: your own video files, free live TV channels, public domain cinema, and LibriVox audiobooks. No account, no server in the middle — nothing leaves your device.</p>
      <div class="card-tags">
        <span class="tag">Android</span><span class="tag">Live TV</span><span class="tag">Public domain</span><span class="tag">Audiobooks</span>
      </div>
      <div class="card-actions">
        <span class="btn-card disabled">Coming Soon to Google Play</span>
      </div>
    </div>

  </div>
</div>

